void nam_a2lite_reset(nam_a2lite_t* inst) {
    memset(inst->state, 0, sizeof(*inst->state));
    memset(inst->la0_hbuf, 0, sizeof(inst->la0_hbuf));
}

void nam_a2lite_set_weights(nam_a2lite_t* inst, const nam_a2lite_weights_t* weights) {
    inst->weights = weights;
}

void nam_a2lite_init(nam_a2lite_t* inst, const nam_a2lite_weights_t* weights, nam_a2lite_state_t* state) {
    inst->weights = weights;
    inst->state = state;
    nam_a2lite_reset(inst);
}

