        state->la0_l1_wp += nf; if (state->la0_l1_wp >= (15 + NAM_A2LITE_MAX_BUFFER_SIZE)) state->la0_l1_wp -= (15 + NAM_A2LITE_MAX_BUFFER_SIZE);
