        state->la0_l5_wp += nf; if (state->la0_l5_wp >= (505 + NAM_A2LITE_MAX_BUFFER_SIZE)) state->la0_l5_wp -= (505 + NAM_A2LITE_MAX_BUFFER_SIZE);
        state->la0_l6_wp += nf; if (state->la0_l6_wp >= (1195 + NAM_A2LITE_MAX_BUFFER_SIZE)) state->la0_l6_wp -= (1195 + NAM_A2LITE_MAX_BUFFER_SIZE);
        state->la0_l7_wp += nf; if (state->la0_l7_wp >= (5 + NAM_A2LITE_MAX_BUFFER_SIZE)) state->la0_l7_wp -= (5 + NAM_A2LITE_MAX_BUFFER_SIZE);
        state->la0_l8_wp += nf; if (state->la0_l8_wp >= (15 + NAM_A2LITE_MAX_BUFFER_SIZE)) state->la0_l8_wp -= (15 + NAM_A2LITE_MAX_BUFFER_SIZE);
        state->la0_l9_wp += nf; if (state->la0_l9_wp >= (35 + NAM_A2LITE_MAX_BUFFER_SIZE)) state->la0_l9_wp -= (35 + NAM_A2LITE_MAX_BUFFER_SIZE);
        state->la0_l10_wp += nf; if (state->la0_l10_wp >= (85 + NAM_A2LITE_MAX_BUFFER_SIZE)) state->la0_l10_wp -= (85 + NAM_A2LITE_MAX_BUFFER_SIZE);
        state->la0_l11_wp += nf; if (state->la0_l11_wp >= (205 + NAM_A2LITE_MAX_BUFFER_SIZE)) state->la0_l11_wp -= (205 + NAM_A2LITE_MAX_BUFFER_SIZE);
